// Generates src/components/logo-paths.ts from the official logo SVGs so the logo can be drawn inline,
// with the cursor's shapes separable from the lettering (for the hover nudge). Re-run after the asset library
// logo changes: npm run logo. scripts/logo.test.mjs checks the generated file still matches the SVGs.
import {readFileSync,writeFileSync} from 'node:fs';
import path from 'node:path';
const root=path.resolve(import.meta.dirname,'..');
const read=name=>readFileSync(path.join(root,'public/website-assets',name),'utf8');
export const shapes=svg=>[...svg.matchAll(/<path d="([^"]+)" fill="([^"]+)" transform="([^"]+)"/g)].map(m=>({d:m[1],fill:m[2].toUpperCase(),transform:m[3]}));
export function build(){
 const source=read('compsoc-blue.svg');const viewBox=source.match(/viewBox="([^"]+)"/)[1];
 const cursor=new Set(shapes(read('cursor-blue.svg')).map(p=>p.transform+p.d));
 const all=shapes(source);if(all.length===0)throw new Error('no logo shapes found');
 const pick=inCursor=>all.filter(p=>cursor.has(p.transform+p.d)===inCursor).map(({d,transform,fill})=>({d,transform,accent:fill==='#00A1CC'}));
 const logo={viewBox,word:pick(false),cursor:pick(true)};
 if(logo.cursor.length!==cursor.size)throw new Error(`expected ${cursor.size} cursor shapes in the logo, found ${logo.cursor.length}`);
 return logo;
}
if(process.argv[1]===import.meta.filename){
 const logo=build();
 writeFileSync(path.join(root,'src/components/logo-paths.ts'),`// Generated by scripts/generate-logo.mjs from public/website-assets/compsoc-blue.svg and cursor-blue.svg. Do not edit by hand.\nexport const logo=${JSON.stringify(logo)} as const;\n`);
 console.log(`logo-paths.ts: ${logo.word.length} lettering shapes, ${logo.cursor.length} cursor shapes`);
}
